function ground(o, l, d) {
  // Immediate survival: if starving and carrying nothing, eat anything (risk is unavoidable)
  if (o.hunger > 90 && !o.carrying) return 'eat';
  if (o.hunger > 70 && o.carrying) return 'eat';

  let harm = 0, feed = 0, total = 0;
  for (const b of d) {
    if (b.key !== l.key) continue;
    total++;
    if (b.harmed) harm++; else feed++;
  }

  // High confidence safety: carry if possible, eat if full hands
  if (harm === 0 && feed >= 3) return o.carrying ? 'eat' : 'carry';

  // Definitive poison: leave immediately to save hunger cost
  if (harm > 0 && feed === 0) return 'leave';

  // Ambiguous/Novel: rely on traits for prediction
  let safeScore = 0;
  // Reward traits shared with known-safe fruits, penalize traits shared with known-poisonous
  for (const b of d) {
    if (b.key === l.key) continue;
    const match = (l.color === b.color && l.shape === b.shape && l.smell === b.smell);
    if (!match) continue;
    if (b.harmed) safeScore -= 2; // Strong penalty for shared traits with poison
    else safeScore += 1; // Weak reward for shared traits with food
  }

  // If traits suggest danger, leave (cheaper to starve slightly than die from poison)
  if (safeScore < -1) return 'leave';

  // If traits suggest safety or neutral, and hunger is manageable, taste to gather data
  if (o.hunger < 60 && safeScore >= 0) return 'taste';

  // High hunger overrides caution if no known poison: eat
  if (o.hunger > 50) return 'eat';

  return o.innate;
}

function wants(o, l, d) {
  if (o.hunger > 60) return true;

  let harm = 0, feed = 0, total = 0;
  for (const b of d) {
    if (b.key !== l.key) continue;
    total++;
    if (b.harmed) harm++; else feed++;
  }

  // Pursue known good food
  if (harm === 0 && feed >= 3) return true;

  // Avoid known poison
  if (harm > 0 && feed === 0) return false;

  // Investigate novel or ambiguous fruits only if not desperate
  if (total === 0 || (feed > 0 && harm > 0)) return o.hunger < 50;

  return o.innate;
}

