function ground(obs, look, diary) {
  // Starvation override: Eat if imminent death, regardless of risk.
  if (obs.hunger >= 95) return 'eat';

  const stats = analyze(look.key, diary);

  // If proven safe and delicious, eat immediately to satisfy hunger.
  if (stats.safe && stats.good) return 'eat';

  // If proven poisonous or neutral-bad, leave it.
  if (stats.poisoned || stats.neutralBad) return 'leave';

  // Ambiguous/Unknown: Taste only if we have enough margin to survive a potential hit.
  // Margin = hungerMax - currentHunger + potential recovery from a small taste.
  // A taste gives ~5 hunger relief but risks +20 damage. Safe buffer needed > 15.
  if (obs.hunger < 75) return 'taste';

  // Too hungry to risk death, but not dead yet. 
  // If we have *any* chance it's good (not strictly proven bad), keep tasting? 
  // No, if hunger is high and unknown, the risk of death is too high for a taste.
  // However, if she is carrying something, she can't eat anyway. 
  // But ground() decides on the fruit. If she is full-ish, leave.
  return 'leave';
}

function wants(obs, look, diary) {
  const action = ground(obs, look, diary);
  return action === 'taste' || action === 'eat';
}

function analyze(key, diary) {
  let safe = 0, poisoned = 0, good = 0; // 'good' means fed significantly
  for (const b of diary) {
    if (b.key !== key) continue;
    if (b.harmed) {
      poisoned++;
    } else if (b.before - b.after > 10) { // Significant hunger reduction
      good++;
      safe++;
    } else {
      // Tasted, didn't die, but didn't get much food. Ambiguous.
      safe++; 
    }
  }

  const total = safe + poisoned;
  if (total === 0) return { safe: false, poisoned: false, good: false, neutralBad: true };

  // If any evidence of poisoning, it's dangerous unless overwhelming evidence against it.
  if (poisoned > 0 && safe <= poisoned) return { safe: false, poisoned: true, good: false, neutralBad: false };

  // If no poison and significant feeding, it's good.
  if (good > 0 && poisoned === 0) return { safe: true, poisoned: false, good: true, neutralBad: false };

  // No poison but no significant food value. Neutral/Bad.
  return { safe: true, poisoned: false, good: false, neutralBad: true };
}

